//! Payload version fixtures.
//!
//! Every payload version ever written is frozen here as literal bytes next to the value it must
//! decode to. When a payload changes (`docs/guides/adding-a-signal.md`, "Payload evolution"),
//! bump its version, keep the old fixtures, and add fixtures for the new version: this test then
//! proves the decoder still reads every historical version while the encoder writes the newest.
//!
//! The bytes below are written by hand from the layout rules in `src/codec.rs`, not generated by
//! the encoder, so they are an independent check on it.

// Test code: a failed unwrap is the failure report. clippy.toml only exempts `#[test]` bodies, not
// helpers in integration-test crates.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::collections::BTreeSet;

use tinwave_signals::*;

struct Fixture {
    version: u8,
    payload: SignalPayload,
    /// `None` for kinds without fields (stored as SQL `NULL`).
    bytes: Option<&'static [u8]>,
}

fn v1(payload: SignalPayload, bytes: &'static [u8]) -> Fixture {
    Fixture {
        version: 1,
        payload,
        bytes: Some(bytes),
    }
}

fn section(kind: SectionKind, index: u8) -> Section {
    Section::new(kind, index).unwrap()
}

fn pos(ds: u32) -> PositionDs {
    PositionDs::new(ds).unwrap()
}

#[allow(clippy::too_many_lines)]
fn fixtures() -> Vec<Fixture> {
    use SignalPayload as P;
    vec![
        // version byte, from, to, gesture, input, section, 2 x elapsed (LE)
        v1(
            P::VolumeChanged(VolumePayload {
                from: Volume::from_raw(0x66),
                to: Volume::from_raw(0x99),
                gesture: GestureTime::from_raw(8),
                input: InputSource::Mouse,
                section: section(SectionKind::Chorus, 2),
                since_track_start: ElapsedDs::from_ds(123),
                since_section_start: ElapsedDs::from_ds(40),
            }),
            &[0x01, 0x66, 0x99, 0x08, 0x00, 0x23, 0x7b, 0x00, 0x28, 0x00],
        ),
        v1(
            P::SystemVolumeChanged(SystemVolumePayload {
                from: Volume::from_raw(0x80),
                to: Volume::from_raw(0x8c),
                gesture: GestureTime::from_raw(12),
                input: InputSource::System,
                section: Section::UNKNOWN,
                since_track_start: ElapsedDs::from_ds(600),
                since_section_start: ElapsedDs::from_ds(0),
                endpoint_class: OutputClass::Headphones,
            }),
            &[
                0x01, 0x80, 0x8c, 0x0c, 0x07, 0x08, 0x58, 0x02, 0x00, 0x00, 0x00,
            ],
        ),
        v1(
            P::MuteToggled(MutePayload {
                muted: true,
                input: InputSource::Keyboard,
            }),
            &[0x01, 0x01, 0x01],
        ),
        // rate is hundredths minus 50: 1.00x = 0x32, 1.25x = 0x4b
        v1(
            P::RateChanged(RatePayload {
                from: Rate::from_raw(0x32),
                to: Rate::from_raw(0x4b),
                input: InputSource::Mouse,
                section: section(SectionKind::Verse, 1),
            }),
            &[0x01, 0x32, 0x4b, 0x00, 0x11],
        ),
        v1(
            P::Skipped(SkipPayload {
                fraction: Fraction::from_raw(26),
                input: InputSource::MediaKey,
                section: section(SectionKind::Intro, 0),
                queue_origin: QueueOrigin::Radio,
            }),
            &[0x01, 0x1a, 0x02, 0x00, 0x01],
        ),
        // 2400 ds = varint e0 12; 50 ds = 32
        v1(
            P::Completed(CompletedPayload {
                listened_ds: pos(2400),
                paused_ds: pos(50),
            }),
            &[0x01, 0xe0, 0x12, 0x32],
        ),
        v1(
            P::SeekForward(SeekPayload {
                from_ds: pos(100),
                to_ds: pos(600),
                section_from: section(SectionKind::Intro, 0),
                section_to: section(SectionKind::Verse, 1),
                input: InputSource::Keyboard,
            }),
            &[0x01, 0x64, 0xd8, 0x04, 0x00, 0x11, 0x01],
        ),
        v1(
            P::SeekBack(SeekPayload {
                from_ds: pos(600),
                to_ds: pos(300),
                section_from: section(SectionKind::Chorus, 2),
                section_to: section(SectionKind::Verse, 1),
                input: InputSource::Mouse,
            }),
            &[0x01, 0xd8, 0x04, 0xac, 0x02, 0x23, 0x11, 0x00],
        ),
        v1(
            P::Replayed(ReplayedPayload { loop_count: 3 }),
            &[0x01, 0x03],
        ),
        v1(
            P::RepeatModeChanged(RepeatModePayload {
                mode: RepeatMode::One,
            }),
            &[0x01, 0x02],
        ),
        v1(
            P::Paused(PausedPayload {
                input: InputSource::MediaKey,
            }),
            &[0x01, 0x02],
        ),
        // 900 ds = varint 84 07; Remote is tag 06 plus the slot
        v1(
            P::Resumed(ResumedPayload {
                pause_ds: pos(900),
                input: InputSource::Remote(3),
            }),
            &[0x01, 0x84, 0x07, 0x06, 0x03],
        ),
        v1(
            P::QueuedNext(QueuedPayload {
                from_view: View::Album,
            }),
            &[0x01, 0x02],
        ),
        v1(
            P::QueuedLater(QueuedPayload {
                from_view: View::Search,
            }),
            &[0x01, 0x05],
        ),
        v1(
            P::RemovedFromQueue(RemovedFromQueuePayload {
                was_radio_pick: true,
            }),
            &[0x01, 0x01],
        ),
        // zigzag(-3) = 5
        v1(
            P::QueueReordered(QueueReorderedPayload { distance: -3 }),
            &[0x01, 0x05],
        ),
        v1(
            P::PlayStarted(PlayStartedPayload {
                origin: PlayOrigin::Playlist,
                input: InputSource::Tray,
            }),
            &[0x01, 0x03, 0x03],
        ),
        v1(
            P::Rated(RatedPayload {
                stars: Stars::new(4).unwrap(),
            }),
            &[0x01, 0x04],
        ),
        v1(
            P::PlaylistAdded(PlaylistEditPayload {
                playlist_id: 300,
                playlist_kind: PlaylistKind::Smart,
            }),
            &[0x01, 0xac, 0x02, 0x01],
        ),
        v1(
            P::PlaylistRemoved(PlaylistEditPayload {
                playlist_id: 5,
                playlist_kind: PlaylistKind::Manual,
            }),
            &[0x01, 0x05, 0x00],
        ),
        // TITLE | GENRE = bits 0 and 4 = 0x11
        v1(
            P::MetadataEdited(MetadataEditedPayload {
                fields: MetadataFields::TITLE.with(MetadataFields::GENRE),
            }),
            &[0x01, 0x11],
        ),
        // hash 0xdeadbeef is little endian; 130 results = varint 82 01
        v1(
            P::SearchPerformed(SearchPerformedPayload {
                query_len: 7,
                query_hash: Hash32(0xdead_beef),
                result_count: 130,
                scope: SearchScope::Albums,
            }),
            &[0x01, 0x07, 0xef, 0xbe, 0xad, 0xde, 0x82, 0x01, 0x02],
        ),
        v1(
            P::SearchResultOpened(SearchResultOpenedPayload {
                rank: 2,
                entity_kind: EntityKind::Artist,
            }),
            &[0x01, 0x02, 0x02],
        ),
        v1(
            P::SearchNoResult(SearchNoResultPayload {
                query_hash: Hash32(0x1234_5678),
            }),
            &[0x01, 0x78, 0x56, 0x34, 0x12],
        ),
        v1(
            P::ViewOpened(ViewOpenedPayload { view: View::Lyrics }),
            &[0x01, 0x09],
        ),
        v1(
            P::WindowState(WindowStatePayload {
                state: WindowStateKind::Minimized,
            }),
            &[0x01, 0x02],
        ),
        v1(
            P::OutputDeviceChanged(OutputDevicePayload {
                class: OutputClass::Bluetooth,
                transport: OutputTransport::Bluetooth,
                form_factor: 3,
                device_hash: Hash32(0x0bad_f00d),
            }),
            &[0x01, 0x02, 0x00, 0x03, 0x0d, 0xf0, 0xad, 0x0b],
        ),
        // treble -2 dB is 0xfe (two's complement)
        v1(
            P::EqChanged(EqPayload {
                preset: 3,
                bass_db: 6,
                treble_db: -2,
            }),
            &[0x01, 0x03, 0x06, 0xfe],
        ),
        v1(
            P::ExclusiveModeToggled(ExclusiveModePayload { on: true }),
            &[0x01, 0x01],
        ),
        v1(
            P::CrossfadeChanged(CrossfadePayload { crossfade_ds: 30 }),
            &[0x01, 0x1e],
        ),
        v1(
            P::SessionStarted(SessionStartedPayload {
                start_origin: PlayOrigin::Resume,
            }),
            &[0x01, 0x06],
        ),
        v1(
            P::SessionEnded(SessionEndedPayload {
                tracks: 25,
                minutes: 130,
            }),
            &[0x01, 0x19, 0x82, 0x01],
        ),
        // DAYPART | WEATHER = bits 0 and 3 = 0x09
        v1(
            P::RadioFeedback(RadioFeedbackPayload {
                kind: RadioFeedbackKind::NeverInContext,
                context_scope: ContextScope::DAYPART.with(ContextScope::WEATHER),
            }),
            &[0x01, 0x01, 0x09],
        ),
        v1(
            P::ExplanationOpened(ExplanationOpenedPayload { reason_kind: 4 }),
            &[0x01, 0x04],
        ),
        // Kinds without fields: stored as NULL, version-less.
        Fixture {
            version: 1,
            payload: P::PreviousPressed,
            bytes: None,
        },
        Fixture {
            version: 1,
            payload: P::Favorited,
            bytes: None,
        },
        Fixture {
            version: 1,
            payload: P::Unfavorited,
            bytes: None,
        },
        Fixture {
            version: 1,
            payload: P::ArtworkChanged,
            bytes: None,
        },
    ]
}

#[test]
fn every_event_kind_has_a_fixture() {
    let with_fixture: BTreeSet<_> = fixtures().iter().map(|f| f.payload.kind()).collect();
    let events: BTreeSet<_> = SignalKind::events().collect();
    assert_eq!(with_fixture, events);
}

#[test]
fn every_supported_version_of_every_kind_has_a_fixture() {
    let fixtures = fixtures();
    for kind in SignalKind::events().filter(|k| k.payload_version().is_some()) {
        assert!(
            kind.supported_payload_versions()
                .contains(&kind.payload_version().unwrap()),
            "{kind}: the current version must be decodable"
        );
        for &version in kind.supported_payload_versions() {
            assert!(
                fixtures
                    .iter()
                    .any(|f| f.payload.kind() == kind && f.version == version),
                "{kind} v{version} is supported but has no fixture"
            );
        }
    }
}

#[test]
fn decoder_reads_every_fixture_of_every_version() {
    for f in fixtures() {
        let kind = f.payload.kind();
        assert_eq!(
            SignalPayload::decode(kind, f.bytes),
            Ok(f.payload),
            "{kind} v{}",
            f.version
        );
        if let Some(bytes) = f.bytes {
            assert_eq!(bytes[0], f.version, "{kind}: fixture version byte");
            assert!(
                kind.supported_payload_versions().contains(&f.version),
                "{kind} v{} has a fixture but the decoder dropped it",
                f.version
            );
        }
    }
}

#[test]
fn encoder_writes_the_current_version_exactly_as_fixed() {
    for f in fixtures() {
        let kind = f.payload.kind();
        let is_current = match kind.payload_version() {
            Some(current) => current == f.version,
            None => true,
        };
        if is_current {
            let encoded = f.payload.encode().unwrap();
            assert_eq!(
                encoded.as_ref().map(EncodedPayload::as_bytes),
                f.bytes,
                "{kind}"
            );
        }
    }
}

#[test]
fn unknown_versions_are_rejected_not_guessed() {
    for kind in SignalKind::events().filter(|k| k.payload_version().is_some()) {
        let supported = kind.supported_payload_versions();
        for version in [0u8, 2, 255] {
            if supported.contains(&version) {
                continue;
            }
            assert_eq!(
                SignalPayload::decode(kind, Some(&[version, 0, 0, 0, 0, 0, 0, 0])),
                Err(SignalsError::UnsupportedVersion { kind, version }),
                "{kind}"
            );
        }
    }
}

#[test]
fn truncated_and_padded_payloads_are_rejected() {
    for f in fixtures() {
        let (Some(bytes), kind) = (f.bytes, f.payload.kind()) else {
            continue;
        };
        for cut in 0..bytes.len() {
            assert!(
                SignalPayload::decode(kind, Some(&bytes[..cut])).is_err(),
                "{kind}: {cut}-byte prefix must not decode"
            );
        }
        let mut padded = bytes.to_vec();
        padded.push(0);
        assert_eq!(
            SignalPayload::decode(kind, Some(&padded)),
            Err(SignalsError::TrailingBytes(1)),
            "{kind}"
        );
    }
}
